model Task {
  id: ID
  title: String
  done: Bool
}

component TaskItem(task: Task, onDelete: Fn) {
  row gap=2 align=center {
    checkbox task.done
    text task.title muted=task.done
    button "x" small danger -> onDelete(task.id)
  }
}

page Home "/" {
  state tasks: Task[] = []
  state draft = ""

  computed pending = tasks.filter(t => !t.done).length

  fn add() {
    let title = draft.trim()
    if title == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: title, done: false })
    draft = ""
  }

  fn remove(id) {
    tasks = tasks.filter(t => t.id != id)
  }

  column gap=4 {
    title "Tareas"
    row gap=2 align=center {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    for t in tasks key t.id {
      TaskItem task=t onDelete=remove
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending} pendientes` muted
    }
  }
}

