page Login "/" {
  state email = ""
  state password = ""
  state sent = false

  computed valid = email.includes("@") && password.length >= 8

  fn submit() {
    if !valid { return }
    sent = true
  }

  column gap=4 pad=4 {
    if sent {
      title `Bienvenido, ${email}`
    } else {
      title "Iniciar sesión"
      form gap=3 -> submit() {
        input email type=email label="Email" placeholder="Email" autocomplete="email" required
        input password type=password label="Contraseña" placeholder="Contraseña" autocomplete="current-password" required
        button "Entrar" primary disabled=(!valid)
      }
    }
  }
}

