model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

const PRODUCTS = [
  { id: "1", name: "Remera", price: 15.5 },
  { id: "2", name: "Zapatillas", price: 59.99 },
  { id: "3", name: "Gorra", price: 9.9 }
]

page Shop "/" {
  state cart: CartItem[] = []

  computed total = cart.reduce((s, i) => s + i.price * i.qty, 0)
  computed totalText = total.toFixed(2)

  fn add(p) {
    let found = cart.find(i => i.id == p.id)
    if found {
      found.qty++
    } else {
      cart.push({ id: p.id, name: p.name, price: p.price, qty: 1 })
    }
  }

  fn inc(item) {
    item.qty++
  }

  fn dec(item) {
    if item.qty <= 1 {
      cart = cart.filter(i => i.id != item.id)
    } else {
      item.qty--
    }
  }

  column gap=6 {
    title "Tienda" tag=h1
    card pad=4 {
      column gap=3 {
        title "Productos"
        for p in PRODUCTS key p.id {
          row gap=3 align=center justify=between {
            text p.name bold
            text `$${p.price.toFixed(2)}` muted
            button "Agregar" primary -> add(p)
          }
        }
      }
    }
    card pad=4 {
      column gap=3 {
        title "Carrito"
        if cart.length == 0 {
          text "El carrito está vacío" muted
        } else {
          for item in cart key item.id {
            row gap=3 align=center justify=between {
              text item.name bold
              text `$${item.price.toFixed(2)}` muted
              row gap=2 align=center {
                button "-" small -> dec(item)
                text `${item.qty}`
                button "+" small -> inc(item)
              }
              text `$${(item.price * item.qty).toFixed(2)}`
            }
          }
        }
        divider
        text `Total: $${totalText}` bold large
      }
    }
  }
}

