  name: String min=1 max=100
  email: String
}

api users: User

page Users "/" {
  state name = ""
  state email = ""
  state error = ""

  data users = api.users.list()

  fn add() {
    if !email.includes("@") {
      error = "Email inválido"
      return
    }
    error = ""
    try {
      api.users.create({ name: name, email: email })
      name = ""
      email = ""
    } catch (e) {
      error = e.message
    }
  }

  fn del(id) {
    api.users.remove(id)
  }

  column gap=4 {
    title "Usuarios"
    input name placeholder="Nombre"
    input email placeholder="Email"
    button "Agregar" primary -> add()
    if error != "" {
      text error danger
    }
    for u in users key u.id {
      row gap=3 align=center {
        text u.name bold
        text u.email muted
        button "Borrar" danger small -> del(u.id)
      }
    }
  }
}

