model Item {
  id: ID
  name: String min=1 max=100
  bought: Bool = false
}

api items: Item

page Shopping "/" {
  state draft = ""
  data items = api.items.list()
  computed pending = items.filter(i => !i.bought).length

  fn add(name) {
    const n = name.trim()
    if n == "" { return }
    api.items.create({ name: n, bought: false })
    draft = ""
  }

  fn buy(id) {
    api.items.update(id, { bought: true })
  }

  fn del(id) {
    api.items.remove(id)
  }

  column gap=4 {
    title "Lista de compras"
    text `${pending} por comprar` bold
    row gap=2 {
      input draft placeholder="Producto" -> add(draft)
      button "Agregar" primary -> add(draft)
    }
    for i in items key i.id {
      row gap=2 align=center {
        text i.bought ? `${i.name} ✓` : i.name
        button "Comprado" small disabled=i.bought -> buy(i.id)
        button "Borrar" small danger -> del(i.id)
      }
    }
  }
}

