model Author {
  id: ID
  name: String min=1
}

model Post {
  id: ID
  title: String min=1
  author: Author
}

api authors: Author
api posts: Post

page Blog "/" {
  state authorName = ""
  state title = ""
  state authorId = ""
  state error = ""

  data authors = api.authors.list()
  data posts = api.posts.list({ include: ["post.author"] })

  fn createAuthor() {
    if authorName.trim() == "" { return }
    api.authors.create({ name: authorName.trim() })
    authorName = ""
  }

  fn publish() {
    if title.trim() == "" || authorId == "" { return }
    api.posts.create({ title: title.trim(), author: authorId })
    title = ""
  }

  fn removeAuthor(id) {
    error = ""
    try {
      await api.authors.remove(id)
    } catch (e) {
      error = "El autor tiene posts"
    }
  }

  column gap=4 {
    title "Blog" tag=h1

    row gap=2 {
      input authorName placeholder="Autor" -> createAuthor()
      button "Crear autor" primary -> createAuthor()
    }

    row gap=2 {
      input title placeholder="Título"
      select authorId options=(authors.map(a => ({ value: a.id, label: a.name }))) placeholder="Elegir autor"
      button "Publicar" primary -> publish()
    }

    if error != "" {
      text error danger
    }

    title "Posts" tag=h2
    for p in posts key p.id {
      card pad=3 {
