page Products "/" {
  state name = ""
  state code = ""
  state price = ""
  state error = ""

  data items = api.products.list()

  fn save() {
    error = ""
    if name.trim().length < 3 {
      error = "Nombre muy corto"
      return
    }
    const p = Number(price)
    if price == "" || isNaN(p) || p < 0 {
      error = "Precio inválido"
      return
    }
    try {
      await api.products.create({ name: name.trim(), code: code, price: p })
      name = ""
      code = ""
      price = ""
    } catch (e) {
      if e.status == 409 {
        error = "Código repetido"
      } else if e.details?.field == "name" {
        error = "Nombre muy corto"
      } else if e.details?.field == "price" {
        error = "Precio inválido"
      } else {
        error = e.message
