model Profile {
  id: ID
  photo: File? max=2000000 accept="image/*"
}

api profiles: Profile

page Profile "/" {
  data list = api.profiles.list()
  state picked: File? = null
  state busy = false
  state err = ""

  computed current = list.length > 0 ? list[0] : null

  fn upload() {
    if !picked { return }
    busy = true
    err = ""
    try {
      if current {
        await api.profiles.update(current.id, { photo: picked })
      } else {
        await api.profiles.create({ photo: picked })
      }
      picked = null
      notify("Foto subida", "success")
    } catch (e) {
      err = e.message
    } finally {
      busy = false
    }
  }

  column gap=4 {
    title "Perfil" tag=h1
    file picked accept="image/*" label="Foto de perfil"
    button "Subir" primary disabled=(!picked || busy) -> upload()
    if err != "" {
      text err danger
    }
    if current && current.photo {
      image current.photo.url alt="Foto de perfil" width=200
    } else {
      text "Todavía no hay foto" muted
    }
  }
}

