page Items "/" {
  const ITEMS = Array.from({ length: 23 }, (_, i) => `Ítem ${i + 1}`)
  const PER_PAGE = 10
  const TOTAL_PAGES = Math.ceil(ITEMS.length / PER_PAGE)

  state page = 1
  computed visible = ITEMS.slice((page - 1) * PER_PAGE, page * PER_PAGE)

  fn prev() {
    if page > 1 { page-- }
  }
  fn next() {
    if page < TOTAL_PAGES { page++ }
  }

  column gap=4 {
    list {
      for t in visible key t {
        item t
      }
    }
    text `Página ${page} de ${TOTAL_PAGES}`
    row gap=2 {
      button "Anterior" disabled=(page == 1) -> prev()
      button "Siguiente" primary disabled=(page == TOTAL_PAGES) -> next()
    }
  }
}

