page Cronometro "/" {
  state n = 0
  state running = false
  ref timer

  fn start() {
    if timer != null { return }
    running = true
    timer = setInterval(() => { n++ }, 100)
  }

  fn pause() {
    if timer != null {
      clearInterval(timer)
      timer = null
    }
    running = false
  }

  fn reset() {
    pause()
    n = 0
  }

  mount {
    cleanup {
      if timer != null {
        clearInterval(timer)
        timer = null
      }
    }
  }

  column gap=4 pad=4 {
    title `Tiempo: ${n}`
    row gap=2 {
      button "Iniciar" primary -> start()
      button "Pausar" -> pause()
      button "Reiniciar" danger -> reset()
    }
  }
}

