model Vote {
  id: ID
  choice: String
}

api votes: Vote

server fn vote(choice) {
  if choice != "dog" && choice != "cat" {
    fail("Opción inválida", 400)
  }
  db.votes.create({ choice: choice })
  return true
}

server fn resetVotes() {
  let rows = db.votes.list({ limit: 1000 })
  while rows.length > 0 {
    for r in rows {
      db.votes.remove(r.id)
    }
    rows = db.votes.list({ limit: 1000 })
  }
  return true
}

server fn results() {
  let dogs = db.votes.count({ where: { choice: "dog" } })
  let cats = db.votes.count({ where: { choice: "cat" } })
  let total = dogs + cats
  let dogsPct = total == 0 ? 0 : Math.round(dogs * 100 / total)
  let catsPct = total == 0 ? 0 : Math.round(cats * 100 / total)
  return { dogs: dogs, cats: cats, dogsPct: dogsPct, catsPct: catsPct }
}

page Poll "/" {
  data stats = server.results()

  computed dogs = stats ? stats.dogs : 0
  computed cats = stats ? stats.cats : 0
  computed dogsPct = stats ? stats.dogsPct : 0
  computed catsPct = stats ? stats.catsPct : 0

  fn cast(choice) {
    await server.vote(choice)
    stats.reload()
  }

  fn reset() {
    await server.resetVotes()
    stats.reload()
  }

  column gap=4 {
    title "Encuesta: ¿Perros o Gatos?" tag=h1
    row gap=2 {
      button "Votar Perros" primary -> cast("dog")
      button "Votar Gatos" primary -> cast("cat")
    }
    column gap=2 {
      text `Perros: ${dogsPct}% (${dogs} votos)`
      text `Gatos: ${catsPct}% (${cats} votos)`
    }
    button "Reiniciar" danger -> reset()
  }
}

