  num: Number
}

api products: Product

page Catalog "/" {
  state page = 0
  state q = ""
  state seeding = false

  data products = api.products.list({ search: q, sort: "num", limit: 5, offset: page * 5 })
  data total = api.products.count({ search: q })

  fn seed() {
    if seeding { return }
    seeding = true
    try {
      let n = await api.products.count()
      if n == 0 {
        for (let i = 1; i <= 12; i++) {
          await api.products.create({ name: `Producto ${i}`, num: i })
        }
      }
      page = 0
      products.reload()
      total.reload()
    } catch (e) {
      notify(e.message, "danger")
    } finally {
      seeding = false
    }
  }

  column gap=4 {
    title "Catálogo"
    button "Cargar ejemplos" primary disabled=seeding -> seed()
    input q placeholder="Buscar" on:input=(page = 0)
    text `Total: ${total}`
    list {
      for p in products key p.id {
        item p.name
      }
    }
    row gap=2 {
      button "Anterior" disabled=(page == 0) -> { page = page - 1 }
      button "Siguiente" disabled=((page + 1) * 5 >= total) -> { page = page + 1 }
    }
  }
}

