    button "Carrito" primary=(tab == "cart") -> onChange("cart")
  }
}

component Catalog(products: Product[], onAdd: Fn) {
  state query = ""
  computed shown = (sorted ? [...products].sort((a, b) => a.price - b.price) : products).filter(p => p.name.toLowerCase().includes(query.toLowerCase()))
  state sorted = false
  fn toggleSort() {
    sorted = !sorted
  }

  column gap=2 {
    input query placeholder="Buscar"
    button "Ordenar por precio" -> toggleSort()
    grid cols=3 gap=2 {
      for p in shown {
        ProductCard product=p onAdd=onAdd
      }
    }
    if shown.length == 0 {
      text "Sin resultados" muted
    }
  }
}

