component CustomersPage {
  state items: Item[] = [
    { id: 1, name: "Alfa", amount: 10, active: true },
    { id: 2, name: "Beta", amount: 20, active: true },
    { id: 3, name: "Gama", amount: 30, active: false }
  ]
  fn add(name, amount) {
    items.push({ id: Date.now(), name, amount, active: true })
  }

  column gap=2 {
    title "Clientes"
    CustomersForm onAdd=add
    CustomersList items=items
  }
}

component CustomersList(items: Item[]) {
  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        CustomersRow item=item
      }
    }
  }
}

component CustomersRow(item: Item) {
  row gap=2 {
    text item.name bold
    text `Saldo: ${item.amount}`
  }
}

component CustomersForm(onAdd: Fn) {
  state name = ""
  state amount = 0
  state error = ""
  fn submit() {
    if name.trim() == "" {
      error = "Nombre requerido"
      return
    }
    error = ""
    onAdd(name, amount)
    name = ""
    amount = 0
  }

  row gap=2 {
    input name placeholder="Nombre"
    input amount placeholder="Saldo" type=number
    button "Agregar" primary -> submit()
    if error != "" {
      text error danger small
    }
  }
}

