  state error = ""
  fn submit() {
    if name.trim() == "" {
      error = "Nombre requerido"
      return
    }
    error = ""
    onAdd(name, amount)
    name = ""
    amount = 0
  }

  row gap=2 {
    input name placeholder="Nombre"
    input amount placeholder="Saldo" type=number
    button "Agregar" primary -> submit()
    if error != "" {
      text error danger small
    }
  }
}

